INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66787926', 66787926, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BALAI TEKNIK PERKERETAAPIAN KELAS II PALEMBANG', 'Penanganan Perlintasan Sebidang di Wilayah Sumatera Bagian Selatan', 'Pekerjaan Konstruksi', 'Tender', 'Sumatera Selatan, Lahat (Kab.) | Sumatera Selatan, Prabumulih (Kota) | Lampung, Bandar Lampung (Kota)', 2470000000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Keadaan darurat di perlintasan sebidang merupakan kejadian yang tidak normal dimana keadaan ini terjadi secaratiba-tiba kondis i darurat ini dapat menyebabkan kecelakaan yang mengakibatkan timbulnya korban jiwa dan properti. Pada perlintasan sebidang berpotensi menjadikan perlintasan sebidang sebagai titik rawan kecelakaan. Perlintasan sebidang adalah perpotongan antara jalan dengan jalur kereta api. Tingginya instensitas perjalanan kereta api dan lalu lintas jalan raya berkaitan dengan jalan rel kereta api sehingga terjadi persinggungan antara pengguna jalan raya dengan kereta api yang berpotensi terjadinya titik rawan kecelakaan. Perbaikan komponen Jalur Perlintasan Langsung (JPL) pada perlintasan sebidang menjadi dasar untuk dijadikan Penanganan Perlintasan Sebidang di Wilayah Sumatera Bagian Selatan.', 'Persyaratan teknis ini meliputi spesifikasi umum, spesifikasi fungsi, spesifikasi perangkat, spesifikasi instalasi, sebagai berikut : a. Persyaratan Umum • Standar Material 1) Material yang digunakan harus berkualitas tinggi, baik dalam bentuk fisik, Komposisi Kimia maupun pengecatannya. 2) Material, ukuran dan toleransi harus sesuai dengan yang ditentukan oleh DJKA atau sama dengan yang telah digunakan di lintas ini. Persyaratan Perangkat Keras • Karakteristik Electrical Secara umum semua peralatan yang dipasang pada proyek ini harus dapat bekerja normal/tahan terhadap interferensi yang ditimbulkan oleh SUTET/SUTT. Syarat lain yang harus diikuti adalh seperti dibawah ini: 1) Tahanan Isolasi a) Tahanan isolasi antara semua rangkaian listrik dan komponen metal diuji pada 500 VDC minimum 10 M.Ohms. b) I/O Interfces, power cubicles dan cable rack external, tahanan isolasi antara rangkaian listrik dan frame minimum 3 M.Ohms pada 500 VDC 2) Dielectric Strength Isolasi antara rangkaian listrik dan komponen metal harus dapat menahan tegangan 1500 VAC selama satu menit 3) Tahanan Pentanahan. a) Tahanan pentanahan peralatan FSTBI dalam ruangan < 1 ohm. Untuk menjaga keamanan, fitur perangkat keras berikut ini harus diadopsi secara khusus pada desain antarmuka. a) Satu dari dua sistem (1002) untuk fail-safety (SIL3). Perangkat sistem persinyalan FSTBI berbasis SIL3 dapat melayani komunikasi blok stasiun-stasiun pada lintas yang ditetapkan dan menjamin keamanan perjalanan kereta api', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 3, 3006242);
