INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66793450', 66793450, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Lisensi dan Maintenance Perangkat Lunak Rekayasa, Simulasi, dan Basis Data Material', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 2097878000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Paket', 'Pengadaan lisensi/perpanjangan lisensi dan maintenance perangkat lunak untuk mendukung kegiatan riset, rekayasa, simulasi teknik, analisis material, desain engineering, serta keberlanjutan operasional perangkat lunak yang digunakan di lingkungan BRIN. Ruang lingkup paket meliputi pengadaan software Ansys CFD, software ICDD PDF 5+, dan maintenance lisensi perangkat lunak SOLIDWORKS BRIN, termasuk lisensi aktif, hak penggunaan, dukungan pembaruan, dan layanan dukungan teknis sesuai kebutuhan pemanfaatan.', 'Paket pengadaan mencakup: Lisensi/perpanjangan lisensi perangkat lunak Ansys CFD untuk kebutuhan simulasi computational fluid dynamics. Lisensi/perpanjangan lisensi perangkat lunak ICDD PDF 5+ untuk kebutuhan basis data/pengolahan data material. Maintenance lisensi perangkat lunak SOLIDWORKS BRIN untuk menjaga keberlanjutan penggunaan, update, upgrade, dan dukungan teknis resmi selama masa layanan. Ketentuan umum spesifikasi: Lisensi resmi dan sah. Dapat digunakan oleh unit kerja penerima sesuai hak penggunaan. Termasuk aktivasi, pembaruan, dan dukungan teknis sesuai jenis layanan yang dibeli. Kompatibel dengan lingkungan operasional/perangkat yang digunakan instansi. Penyerahan dokumen lisensi, bukti keaslian, dan dokumen pendukung lainnya. Masa layanan/lisensi sesuai kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 3009417);
